ram planner"}, {"id": "14e3c1a5-bc18-4d66-9392-456e8f420e46", "type": "concept", "title": "Health communicator"}, {"id": "ea8b0f11-08f0-48ea-9cce-56eff7739174", "type": "concept", "title": "Coalition partner"}, {"id": "574a4d37-43b4-4cc4-86c0-67cb0b37e022", "type": "concept", "title": "Evaluator and advocate"}]}, {"id": "0a5619ce-90c4-4c02-80e2-792b3575476a", "type": "subtopic", "title": "Behavior change as public health practice", "description": "Students learn that behavior change is shaped by evidence, context, resources, trust, and structural opportunity.", "children": [{"id": "d74ebbf5-c82f-457b-9c35-28246d23c469", "type": "concept", "title": "Evidence-informed strategies"}, {"id": "80e7716a-350b-478a-b916-130618a79080", "type": "concept", "title": "Context and feasibility"}, {"id": "ce5843d9-6b2c-4ec5-a797-0986dff65bcb", "type": "concept", "title": "Trust and credibility"}, {"id": "1b79a303-6787-4146-b9f9-90542872ce2f", "type": "concept", "title": "Policy and environment"}, {"id": "67096921-8dae-4f61-a712-c26e2e333129", "type": "concept", "title": "Sustainability"}]}]}, {"id": "dce58359-cc41-428d-8a98-add86071126a", "type": "topic", "title": "Social and Behavioral Determinants of Health", "description": "Connect individual behavior to social, cultural, economic, political, and environmental contexts.", "children": [{"id": "25654c6d-ed10-495c-b4dc-b46403db4af0", "type": "subtopic", "title": "Determinants framework", "description": "Students connect behavior to the conditions in which people are born, live, work, learn, play, and age.", "children": [{"id": "1a1685ea-58a2-44cd-a547-d74d69477128", "type": "concept", "title": "Economic stability"}, {"id": "18c7f5fd-8fab-47eb-a310-ba71e46f572c", "type": "concept", "title": "Education access"}, {"id": "f9b2ce33-32eb-453e-a938-2b539252eba8", "type": "concept", "title": "Neighborhood and built environment"}, {"id": "5840d8aa-0c56-43e1-b521-d831ebf106c4", "type": "concept", "title": "Health care access"}, {"id": "aaf0e0