ages.", "children": [{"id": "10df9598-049e-4178-b286-9c9227eaca66", "type": "concept", "title": "Consciousness raising"}, {"id": "d93bfcda-95f0-445d-8422-2be53486af29", "type": "concept", "title": "Self-reevaluation"}, {"id": "66dab2cc-0036-44b8-a352-6d1c47c79da8", "type": "concept", "title": "Helping relationships"}, {"id": "5abadcd6-9c6b-4d87-92b5-395daad64229", "type": "concept", "title": "Stimulus control"}, {"id": "08d2b72f-f32c-441f-b77c-a9797700d88c", "type": "concept", "title": "Reinforcement management"}]}, {"id": "a2a47456-3def-4575-b2c3-175f84f08b23", "type": "subtopic", "title": "Relapse and maintenance", "description": "Students learn to treat relapse as information for support rather than failure.", "children": [{"id": "41086212-e992-49f5-be61-95f6151cdc80", "type": "concept", "title": "Triggers"}, {"id": "8993aff5-b185-4919-b65c-0f7995d80d65", "type": "concept", "title": "Coping plans"}, {"id": "abf86673-9898-4a32-84b8-be343adb024d", "type": "concept", "title": "Social support"}, {"id": "94843111-24cb-40c4-9d2a-1c3315278c8b", "type": "concept", "title": "Maintenance routines"}, {"id": "ee32c957-eb18-4a43-820d-7d429b6a6ede", "type": "concept", "title": "Long-term follow-up"}]}]}, {"id": "d92e1afa-ba0b-49da-9ff9-f02b21679b0d", "type": "topic", "title": "Social Cognitive Theory, Self-Efficacy, and Observational Learning", "description": "Apply reciprocal determinism, modeling, reinforcement, and self-efficacy to health education practice.", "children": [{"id": "5c8f434e-81b3-41a1-a23a-80e3d3d71790", "type": "subtopic", "title": "Reciprocal determinism", "description": "Students learn that behavior, personal factors, and environment influence one another.", "children": [{"id": "d63d9540-d426-4b9e-8d34-226485dd37d3", "type": "concept", "title": "Person factors"}, {"id": "da9b28a9-279a-45db-902b-7b5d4bc1c67c", "type": "concept", "title": "Behavior"}, {"id": "b837f6fe-a646-4377-aad6-af72a483755d", "type": "concept", "title": "Environment"}, {"id": "949a6f14-